import { readEvents } from '/Users/eryk.napierala/conductor/workspaces/werk/iqaluit/src/log.ts'
import { fold } from '/Users/eryk.napierala/conductor/workspaces/werk/iqaluit/src/fold.ts'
const g: any = fold(readEvents('/Users/eryk.napierala/conductor/workspaces/werk/iqaluit/.werk/log.jsonl'))
const nodes = new Map<string, any>((g.nodes as any[]).map((n: any) => [n.id, n]))
const isCard = (id: string) => { const n = nodes.get(id); return n && n.kind !== 'option' && n.kind !== 'source' && n.kind !== 'excerpt' && !n.proposed }
const kids = new Map<string, string[]>(), parent = new Map<string,string>()
for (const e of g.edges) if (e.type === 'refines' && isCard(e.from) && isCard(e.to)) { (kids.get(e.to) ?? kids.set(e.to, []).get(e.to)!).push(e.from); parent.set(e.from, e.to) }
const single = (id: string) => (kids.get(id) ?? []).length === 1
const out: string[][] = []
for (const id of kids.keys()) {
  if (!single(id)) continue
  const p = parent.get(id); if (p && single(p)) continue // not chain head
  const chain = [id]; let c = id
  while (single(c)) { c = kids.get(c)![0]; chain.push(c) }
  if (chain.length >= 3) out.push(chain)
}
for (const ch of out) { console.log('---'); for (const id of ch) { const n = nodes.get(id); console.log(`${id} [${n.status}] (${(kids.get(id)??[]).length} kids) ${n.title}`) } }
